Here's a JavaScript implementation for packing and unpacking an array of entities into an ArrayBuffer. The entities will have the following fields: id (4 bits) and size (3 bits).

```javascript
function packEntities(entities) {
  const totalBits = entities.length * 7;
  const arrayBuffer = new ArrayBuffer(Math.ceil(totalBits / 8));
  const bytes = new Uint8Array(arrayBuffer);

  for (let i = 0; i < entities.length; i++) {
    const id = entities[i].id & 0x0F; // Get lower 4 bits
    const size = entities[i].size & 0x07; // Get lower 3 bits
    const entity = (id << 3) | size;

    const byteIndex = Math.floor(i * 7 / 8);
    const bitOffset = (i * 7) % 8;

    bytes[byteIndex] |= entity >>> bitOffset;
    if (bitOffset > 1) {
      bytes[byteIndex + 1] |= entity << (8 - bitOffset);
    }
  }

  return arrayBuffer;
}

function unpackEntities(arrayBuffer) {
  const entities = [];
  const bytes = new Uint8Array(arrayBuffer);
  const totalBits = bytes.length * 8;
  let currentBit = 0;

  while (currentBit < totalBits) {
    const byteIndex = Math.floor(currentBit / 8);
    const bitOffset = currentBit % 8;

    let entity = bytes[byteIndex] << bitOffset;
    if (bitOffset > 1) {
      entity |= bytes[byteIndex + 1] >>> (8 - bitOffset);
    }

    entity &= 0x7F; // Get lower 7 bits
    const id = (entity >>> 3) & 0x0F;
    const size = entity & 0x07;

    entities.push({ id, size });
    currentBit += 7;
  }

  return entities;
}
```

Here's an example of how to use the packing and unpacking functions:

```javascript
const entities = [
  { id: 10, size: 5 },
  { id: 2, size: 3 },
  { id: 15, size: 7 }
];

const packedArrayBuffer = packEntities(entities);
const unpackedEntities = unpackEntities(packedArrayBuffer);

console.log(unpackedEntities);
```

Keep in mind that this implementation assumes the input array (`entities`) will have valid values for `id` and `size` (that is, 4-bit and 3-bit values, respectively). If there's a possibility of receiving invalid values, you should add validation logic before using the provided values.

