{
    public string GetMessage()
    {
        return "Hello from ExampleService!";
    }
}
```

5. Modify the `Program.cs` file to include the registration of your services and configure your host builder. Also, modify your `main` function to build the `host`:

```csharp
using System;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using MyFunctionApp.Services;

var builder = new HostBuilder()
    .ConfigureFunctionsWorkerDefaults()
    .ConfigureServices((hostContext, services) =>
    {
        // Register your custom services here
        services.AddSingleton<IExampleService, ExampleService>();
    });

using var host = builder.Build();
await host.RunAsync();
```

6. Inject the required services in your Azure Functions. First, modify the function constructor to receive the IExampleService:

```csharp
public class ExampleFunction
{
    private readonly IExampleService _exampleService;

