#include "FastLED.h"

#define NUM_LEDS 60 // Number of LEDs on the strip
#define DATA_PIN D2 // LED strip data pin
#define BUTTON_PIN D3 // Button pin
#define COLOR_CHANGE_DELAY 10 // Delay between color changes in milliseconds

CRGB leds[NUM_LEDS];
int currentLED = 0;
