  FastLED.setBrightness(255);
  FastLED.clear(true);
}

void loop() {
  buttonState = !digitalRead(BUTTON_PIN); // Read button state and apply debouncing

  if (buttonState && !lastButtonState) { // Check if button is pressed and the state has changed
    if (currentLED < NUM_LEDS) {
      leds[currentLED] = CHSV(colorHue, 255, 255);
      FastLED.show();
      currentLED++;

      colorHue += 256 / NUM_LEDS; // Increment color hue for rainbow effect
      if (colorHue >= 256) colorHue = 0;
    } else {
      FastLED.clear(); // Clear the strip when the last LED is lit
      FastLED.show();
      currentLED = 0;
    }
    delay(200); // Button debounce delay
  }
  lastButtonState = buttonState;
}
```

This code reads the button state and lights up additional LEDs one by one on each button press, with the colors of the rainbow. Make sure to update NUM_LEDS and adjust data pin (DATA_PIN) and button pin (BUTTON_PIN) according to your connections.

