function initialise() {
  // This function is only called by Google, so we don't need to check if 'google' is defined.

  var mapOptions = {
    center: new google.maps.LatLng(53.478852, -2.247444),
    zoom: 9,
    mapTypeControl: false, // Cannot switch between roadmap/satellite
    panControl: false, // No circular pan control near top left
    zoomControl: false, // No vertical zoom bar near top left
    streetViewControl: false // No StreetView pinman
  };

  map = new google.maps.Map(document.getElementById("map-canvas"), mapOptions);

