    rectangle.setMap(map);
    map.fitBounds(rectangleBounds);
  }
}

if (typeof google !== 'undefined') { // did Google's JavaScript load?
  google.maps.event.addDomListener(window, 'load', initialise);
} else {
  document.addEventListener('DOMContentLoaded', function() {
    document.querySelector('#map-canvas').classList.add('hidden');
    document.querySelector('#broken-map').classList.remove('hidden');
  });
}
```
Here's a breakdown of the changes:

* Replaced `$(document).ready()` with `document.addEventListener('DOMContentLoaded')`. The `ready` event is not supported in all browsers, and `DOMContentLoaded` is a more standard way of waiting for the document to finish loading.
* Replaced `$(element).addClass()` and `$(element).removeClass()` with `element.classList.add()` and `element.classList.remove()`, respectively. This is the vanilla JavaScript way of adding and removing classes from an element.
* Replaced `$(window).load()` with `google.maps.event.addDomListener(window, 'load', initialise)`. The `load` event is not supported in all browsers, and `google.maps.event.addDomListener` is a more standard way of waiting for the map to finish loading.

