Based on the config you provided, the recursion for pagination is already set up with this line:

```
if: "${output.hasNextPage} === true",
```

However, to make this more efficient and readable, you can take advantage of JavaScript's native `async/await` functionality and use a custom function to handle the pagination. Here's an updated config with the custom function:

```
"get-providers-to-fetch": {
  type: "api",
  params: {
    method: "GET",
    url: "https://immo.so/api/providers",
    query: {
      all: "${input.all}",
    },
    async: false,
  },
  next: [
    {
      name: "scrape-providers",
      forEach: true,
      params: {},
    },
  ],
},
"scrape-providers": {
  type: "customFunction",
  implementation: async function scrapeProviderRecursive(input) {
    const fetchData = async (provider, endpoint, page, batchSize, from) => {
      const response = await this.callWorkflowNode({
        name: "scrape-provider",
        input: {
          provider,
          endpoint,
          page,
          batchSize,
          from,
        },
      });

      if (response.output.hasNextPage) {
        return fetchData(provider, endpoint, page, batchSize, response.output.from);
      }
      return response;
    };

    return fetchData(input.provider, input.endpoint, input.page, input.batchSize, input.from);
  },
},
"scrape-provider": {
  type: "api",
  params: {
    method: "GET",
    url: "https://immo.so/api/scrape",
    query: {
      provider: "${input.provider}",
      endpoint: "${input.endpoint}",
      page: "${input.page}",
      batchSize: "${input.batchSize}",
      from: "${input.from}",
    },
    async: false,
  },
},
```

