#include <stdint.h>
#include <stdbool.h>
#include "uart.h"

#define MODBUS_ADDRESS   1
#define MODBUS_FUNCTION  5
#define MODBUS_PORT      UART_PORT1

// Helper function to calculate High and Low bytes of a 16 bit integer
static void SplitInt16(uint16_t input, uint8_t* high, uint8_t* low)
{
    *high = (uint8_t)(input >> 8);
    *low = (uint8_t)(input & 0xFF);
}

// CRC-16 calculation for Modbus
static uint16_t CalculateCRC(const uint8_t* buffer, uint8_t length)
{
    uint16_t crc = 0xFFFF;
    for (uint8_t i = 0; i < length; i++)
    {
        crc ^= buffer[i];
        for (uint8_t j = 0; j < 8; j++)
        {
            if (crc & 0x01)
            {
                crc >>= 1;
                crc ^= 0xA001;
            }
            else
            {
                crc >>= 1;
            }
        }
    }
    return crc;
}

// Set DIO using Modbus write single coil function
void ModbusWriteCoil(uint8_t address, uint16_t coil, bool state)
{
    uint8_t txBuffer[8];
    uint8_t coilHigh, coilLow, valueHigh, valueLow;
    uint16_t crcValue;
    uint8_t crcHigh, crcLow;

    SplitInt16(coil, &coilHigh, &coilLow);
    state ? (valueHigh = 0xFF, valueLow = 0x00) : (valueHigh = 0x00, valueLow = 0x00);

    // Assemble Modbus message
    txBuffer[0] = address;
    txBuffer[1] = MODBUS_FUNCTION;
    txBuffer[2] = coilHigh;
    txBuffer[3] = coilLow;
    txBuffer[4] = valueHigh;
    txBuffer[5] = valueLow;

    // Add CRC for error checking
    crcValue = CalculateCRC(txBuffer, 6);
    SplitInt16(crcValue, &crcHigh, &crcLow);
    txBuffer[6] = crcLow;
    txBuffer[7] = crcHigh;

    // Send the message via UART
    UART_SendData(MODBUS_PORT, txBuffer, sizeof(txBuffer));
}

int main(void)
{
    // Initialize UART and the microcontroller
