```perl
#!/usr/bin/perl
use strict;
use warnings;
use Time::Local;

# Function to check if a given year is a leap year
sub is_leap_year {
    my $year = $_[0];
    return (($year % 4 == 0 && $year % 100 != 0) || ($year % 400 == 0));
}

# Function to validate and parse the input date
sub parse_date {
    my $date_input = $_[0];

    unless ($date_input =~ /^(\d{4})-(\d{2})-(\d{2})$/) {
        die "Invalid date format. Please provide date in YYYY-MM-DD format.\n";
    }

    my ($year, $month, $day) = ($1, $2, $3);

    if ($month < 1 || $month > 12) {
        die "Invalid month.\n";
    } elsif ($day < 1 || ($day > 31 && (($month == 4) || ($month == 6) || ($month == 9) || ($month == 11))) || ($day > 30 && $month == 2) || ($day > 29 && $month == 2 && is_leap_year($year)) || ($day > 28 && $month == 2)) {
        die "Invalid day.\n";
    }

    return ($year, $month, $day);
}

# Program starts here
print "Enter first date (YYYY-MM-DD): ";
my $input_date1 = <STDIN>;
chomp $input_date1;

print "Enter second date (YYYY-MM-DD): ";
my $input_date2 = <STDIN>;
chomp $input_date2;

my ($year1, $month1, $day1) = parse_date($input_date1);
my ($year2, $month2, $day2) = parse_date($input_date2);

my $timestamp1 = timelocal(0, 0, 0, $day1, $month1 - 1, $year1);
my $timestamp2 = timelocal(0, 0, 0, $day2, $month2 - 1, $year2);

my $days_difference = int(abs($timestamp2 - $timestamp1) / (24 * 60 * 60));

print "The number of days between $input_date1 and $input_date2 is $days_difference.\n";
```

This Perl script takes two dates as input, validates them, and calculates the number of days between them. It uses the Time::Local module to convert the dates to Unix timestamps, and then calculates the difference between them while accounting for leap years. The script is well-documented with appropriate comments and variable names.

