def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def is_palindromic(num):
    return str(num) == str(num)[::-1]

def digit_sum(num):
    return sum(int(digit) for digit in str(num))

def palindromic_prime_sum(numbers):
    total = 0
    for num in numbers:
        if is_prime(num) and is_palindromic(num) and digit_sum(num) > 10:
            total += num
    return total

